package dao;
import config.ConexionBD;import java.sql.*;import java.util.*;import negocio.*;
public class IntentoPagoDAOMySQL implements IntentoPagoDAO {
 public IntentoPago iniciar(long ordenId){if(ordenId<=0)throw new IllegalArgumentException("La orden es obligatoria.");try(Connection c=ConexionBD.obtenerConexion()){c.setAutoCommit(false);try{try(PreparedStatement lock=c.prepareStatement("SELECT id FROM ordenes_pago WHERE id=? FOR UPDATE")){lock.setLong(1,ordenId);try(ResultSet r=lock.executeQuery()){if(!r.next())throw new IllegalArgumentException("La orden no existe.");}}int numero;try(PreparedStatement s=c.prepareStatement("SELECT COALESCE(MAX(numero_intento),0)+1 FROM intentos_pago WHERE orden_pago_id=?")){s.setLong(1,ordenId);try(ResultSet r=s.executeQuery()){r.next();numero=r.getInt(1);}}IntentoPago i=new IntentoPago();try(PreparedStatement s=c.prepareStatement("INSERT INTO intentos_pago(orden_pago_id,numero_intento,estado) VALUES(?,?,'INICIADO')",Statement.RETURN_GENERATED_KEYS)){s.setLong(1,ordenId);s.setInt(2,numero);s.executeUpdate();try(ResultSet r=s.getGeneratedKeys()){if(r.next())i.setId(r.getLong(1));}}i.setOrdenPagoId(ordenId);i.setNumeroIntento(numero);i.setEstado(EstadoIntentoPago.INICIADO);c.commit();return i;}catch(Exception e){c.rollback();if(e instanceof RuntimeException x)throw x;throw new RuntimeException("No se pudo iniciar el intento de pago.",e);}finally{c.setAutoCommit(true);}}catch(SQLException e){throw new RuntimeException("No se pudo iniciar el intento de pago.",e);}}
 public void finalizar(long id,EstadoIntentoPago estado,String referencia,String detalle){if(id<=0||estado==null)throw new IllegalArgumentException("El intento y el estado son obligatorios.");String q="UPDATE intentos_pago SET estado=?,referencia_externa=COALESCE(?,referencia_externa),detalle_error=?,fecha_fin=CURRENT_TIMESTAMP WHERE id=?";try(Connection c=ConexionBD.obtenerConexion();PreparedStatement s=c.prepareStatement(q)){s.setString(1,estado.name());nullable(s,2,referencia);nullable(s,3,detalle);s.setLong(4,id);if(s.executeUpdate()!=1)throw new IllegalArgumentException("El intento no existe.");}catch(SQLException e){throw new RuntimeException("No se pudo finalizar el intento.",e);}}
 public List<IntentoPago> listarPorOrden(long ordenId){List<IntentoPago>x=new ArrayList<>();try(Connection c=ConexionBD.obtenerConexion();PreparedStatement s=c.prepareStatement("SELECT * FROM intentos_pago WHERE orden_pago_id=? ORDER BY numero_intento")){s.setLong(1,ordenId);try(ResultSet r=s.executeQuery()){while(r.next()){IntentoPago i=new IntentoPago();i.setId(r.getLong("id"));i.setOrdenPagoId(r.getLong("orden_pago_id"));i.setNumeroIntento(r.getInt("numero_intento"));i.setEstado(EstadoIntentoPago.valueOf(r.getString("estado")));i.setReferenciaExterna(r.getString("referencia_externa"));i.setDetalleError(r.getString("detalle_error"));Timestamp a=r.getTimestamp("fecha_inicio"),b=r.getTimestamp("fecha_fin");if(a!=null)i.setFechaInicio(a.toLocalDateTime());if(b!=null)i.setFechaFin(b.toLocalDateTime());x.add(i);}}return x;}catch(SQLException e){throw new RuntimeException("No se pudieron listar los intentos.",e);}}private void nullable(PreparedStatement s,int p,String v)throws SQLException{if(v==null||v.isBlank())s.setNull(p,Types.VARCHAR);else s.setString(p,v);}
}
